B.bqn=s(["Localizacao aproximada e precisa para mapas e cobertura","Rastreamento do pedido e do estafeta","Calculo de rotas e tempos estimados"],t.s)
B.cOU=new A.q1(B.bqn,null)
B.cSZ=new A.NE("3.5 Comunicacoes e dados tecnicos",null)
